<?php $title='Administrar productos'; ?><div class="level"><div><h1 class="title">Alta de productos</h1><p class="subtitle is-6">Al crear un producto, el sistema calcula el boleto al 7% y crea su rifa.</p></div><a class="button" href="<?= route('admin') ?>">Regresar</a></div><div class="columns"><div class="column is-5"><div class="box"><h2 class="title is-5"><?= $edit?'Editar producto':'Nuevo producto' ?></h2><form method="post" enctype="multipart/form-data"><?= csrf_field() ?><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><div class="field"><label class="label">Nombre</label><input class="input" name="name" required placeholder="Ej. Consola" value="<?= e($edit['name']??'') ?>"></div><div class="field"><label class="label">Descripción</label><textarea class="textarea" name="description"><?= e($edit['description']??'') ?></textarea></div><div class="field"><label class="label">Precio</label><input class="input" name="price" type="number" min="0.01" step="0.01" required value="<?= e((string)($edit['price']??'')) ?>"></div><div class="field"><label class="label">Imagen</label><input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="buttons"><button class="button is-primary"><?= $edit?'Actualizar':'Guardar producto + crear rifa' ?></button><?php if($edit): ?><a class="button is-light" href="<?= route('admin_products') ?>">Cancelar</a><?php endif; ?></div></form></div></div></div><div class="column is-7"><div class="box"><h2 class="title is-5">Productos registrados</h2><div class="table-container"><table class="table is-fullwidth is-hoverable"><thead><tr><th>Imagen</th><th>Producto</th><th>Precio</th><th>Acción</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?php if($p['image_path']): ?><figure class="image is-48x48"><img class="is-rounded" src="<?= e($p['image_path']) ?>"></figure><?php endif; ?></td><td><?= e($p['name']) ?></td><td><?= money($p['price']) ?></td><td><a class="button is-small is-link is-light mr-2" href="<?= route('admin_products',['edit'=>$p['id']]) ?>">Editar</a><form class="is-inline" method="post" action="<?= route('admin_product_delete') ?>" onsubmit="return confirm('¿Eliminar producto?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="button is-small is-danger is-light">Eliminar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
